class Solution {
    public int similarPairs(String[] words){
        Map<Integer,Integer> frequency=new HashMap<>();
        int answer=0;
        for(String word:words){
            int mask=0;
            for(char character:word.toCharArray())mask|=1<<(character-'a');
            answer+=frequency.getOrDefault(mask,0);
            frequency.merge(mask,1,Integer::sum);
        }
        return answer;
    }
}

code.kotlin:
class Solution {
    fun similarPairs(words:Array<String>):Int{
        val frequency=HashMap<Int,Int>();
        var answer=0;
        for(word in words){
            var mask=0;
            for(character in word)mask=mask or (1 shl (character-'a'));
            answer+=frequency[mask]?:0;
            frequency[mask]=(frequency[mask]?:0)+1
        };
        return answer
    }
}

